analyze.mjs.text:
// Classifies a set of per-path probe results (real HTTP responses, collected
// by probe.mjs's live requests) into a verdict about whether a target is
// publicly serving one of its own backup files. Pure function, no I/O, no
// network -- imported identically by the CLI (check.mjs) and the browser
// page (index.html), the same shape `ventures/dotenv-exposure-check/analyze.mjs`
// documents.
//
// The one rule every function in this file is built around, adapted from
// dotenv-exposure-check's own: a backup file's whole purpose is holding a
// full copy of the site or database, so this tool must never become a second
// way to leak what it finds. Two different content shapes need two different
// restraints:
//
//   Archives (zip/tar.gz/gzip/bzip2/7z) are confirmed by their magic bytes
//   only -- the first handful of header bytes probe.mjs already capped the
//   read to. This tool never lists, extracts, or reads a single file out of
//   the archive; a short hex sample of the header is the only "content"
//   ever shown, and that content is structural (a file-format signature),
//   never anything from inside the archive.
//
//   SQL dumps are confirmed by their line SHAPE, the same "verify the real
//   shape, not just an HTTP status" test dotenv-exposure-check applies.
//   Within that shape, `sqlLineKind` below draws a hard line: a schema
//   statement (CREATE/DROP/ALTER/LOCK TABLE) names table structure and is
//   safe to quote as evidence, the same way dotenv-exposure-check quotes a
//   variable NAME rather than its value. A data statement (INSERT/REPLACE/
//   COPY ... FROM stdin) carries actual row *content* -- real customer
//   data, potentially -- and its line text is never quoted anywhere; only
//   a count of how many such lines were seen is ever shown.
//
// What each classification means:
//
//   exposed     The path returned 200 and its body is confirmed either a
//               real archive (matched magic bytes) or a real SQL dump
//               (matched shape) -- not an unrelated page. Two severities:
//                 critical  an archive's magic bytes matched exactly, or
//                           the SQL dump carries an explicit dump-tool
//                           header comment ("-- MySQL dump", "-- pg_dump",
//                           phpMyAdmin's own header) -- the strongest
//                           signal available.
//                 danger    the body has the structural shape of a SQL
//                           dump (multiple CREATE/INSERT-style statement
//                           lines) but no explicit tool header was found --
//                           still real evidence, just one notch softer.
//   blocked     The path returned a clean 401/403/404/410 -- not reachable.
//               A healthy outcome, whether the file was never there or a
//               server rule already denies it.
//   not-backup  The path returned 200, but the body matches neither a known
//               archive signature nor a SQL dump shape (most likely a
//               soft-404 catch-all page, or an HTML/text 200 unrelated to
//               any of this). Reported separately from `blocked` because it
//               says something about the server's behaviour, but it is not
//               evidence of an exposure either way.
//   error       The request itself failed without a clean HTTP status
//               (network error, timeout, a browser's CORS-blocked "failed to
//               fetch"). Never read as either exposed or safe.

// Archive magic-byte signatures, checked at the start of the body. Every one
// of these is a well-documented file-format header, not a guess -- ZIP's
// four-byte local-file-header and end-of-central-directory signatures, gzip's
// two-byte magic, bzip2's three-ASCII-byte "BZh", and 7-Zip's six-byte magic
// are all published in each format's own specification.
const ARCHIVE_SIGNATURES = [
  { name: 'ZIP archive', bytes: [0x50, 0x4b, 0x03, 0x04] },
  { name: 'ZIP archive (empty)', bytes: [0x50, 0x4b, 0x05, 0x06] },
  { name: 'ZIP archive (spanned)', bytes: [0x50, 0x4b, 0x07, 0x08] },
  { name: 'gzip archive', bytes: [0x1f, 0x8b] },
  { name: 'bzip2 archive', bytes: [0x42, 0x5a, 0x68] },
  { name: '7-Zip archive', bytes: [0x37, 0x7a, 0xbc, 0xaf, 0x27, 0x1c] },
];
// tar has no leading magic -- POSIX ustar tar places its "ustar" signature at
// byte offset 257, so it is checked separately rather than folded into the
// list above.
const TAR_MAGIC_OFFSET = 257;
const TAR_MAGIC = [0x75, 0x73, 0x74, 0x61, 0x72]; // "ustar"

const HTML_SNIFF_RE = /<html[\s>]|<!doctype html/i;

const SQL_HEADER_RE =
  /^--\s*(mysql dump|phpmyadmin sql dump|postgresql database dump|dumped from database version|pg_dump)|^--\s*host:.*database:/i;
const SQL_SCHEMA_RE = /^(create table|drop table(\s+if exists)?|alter table|lock tables|unlock tables)\b/i;
const SQL_DATA_RE = /^(insert into|replace into|copy\s+\S+.*from stdin)\b/i;

function toUint8Array(bytes) {
  if (bytes instanceof Uint8Array) return bytes;
  if (Array.isArray(bytes)) return Uint8Array.from(bytes);
  return new Uint8Array(0);
}

function bytesStartWith(bytes, sig, offset = 0) {
  if (bytes.length < offset + sig.length) return false;
  for (let i = 0; i < sig.length; i++) {
    if (bytes[offset + i] !== sig[i]) return false;
  }
  return true;
}

function toHex(bytes, n) {
  return Array.from(bytes.slice(0, n)).map((b) => b.toString(16).padStart(2, '0')).join(' ');
}

/** Matches the capped response bytes against every known archive signature.
 * Returns `{ name, sampleHex }` for the first match, or `null`. The hex
 * sample is a purely structural artifact (a file-format header) -- never
 * content from inside the archive, which this tool never reads. */
export function matchArchiveSignature(rawBytes) {
  const bytes = toUint8Array(rawBytes);
  for (const sig of ARCHIVE_SIGNATURES) {
    if (bytesStartWith(bytes, sig.bytes)) {
      return { name: sig.name, sampleHex: toHex(bytes, 16) };
    }
  }
  if (bytesStartWith(bytes, TAR_MAGIC, TAR_MAGIC_OFFSET)) {
    return { name: 'tar archive (ustar)', sampleHex: toHex(bytes, 16) };
  }
  return null;
}

/** Classifies each non-blank line of decoded text as a SQL dump "header"
 * (a dump tool's own identifying comment), "schema" (safe to quote --
 * table/column structure, never row data) or "data" (never quoted -- may
 * carry real row content) or `null` (not dump-shaped). Exported for tests
 * that need to check the safe/unsafe split directly. */
export function sqlLineKind(line) {
  const t = line.trim();
  if (!t) return null;
  if (SQL_HEADER_RE.test(t)) return 'header';
  if (SQL_SCHEMA_RE.test(t)) return 'schema';
  if (SQL_DATA_RE.test(t)) return 'data';
  return null;
}

/** Scans decoded text for a SQL dump shape. Never returns a "data"
 * (INSERT/REPLACE/COPY ... FROM stdin) line's own text anywhere in its
 * result -- only a count of how many were seen. `schemaSamples` holds up to
 * three schema-statement lines (table/column structure only), capped to 120
 * characters each. */
export function detectSqlDump(text) {
  if (typeof text !== 'string' || !text) return null;
  if (HTML_SNIFF_RE.test(text)) return null;

  const lines = text.split(/\r?\n/);
  let headerLine = null;
  let schemaCount = 0;
  let dataCount = 0;
  const schemaSamples = [];
  let totalContentLines = 0;

  for (const line of lines) {
    const t = line.trim();
    if (!t) continue;
    totalContentLines += 1;
    const kind = sqlLineKind(line);
    if (kind === 'header' && !headerLine) headerLine = t.slice(0, 120);
    else if (kind === 'schema') {
      schemaCount += 1;
      if (schemaSamples.length < 3) schemaSamples.push(t.slice(0, 120));
    } else if (kind === 'data') {
      dataCount += 1;
    }
  }

  if (headerLine) {
    return { severity: 'critical', headerLine, schemaSamples, schemaCount, dataCount, totalContentLines };
  }

  const signalLines = schemaCount + dataCount;
  // Require at least two structural signal lines AND a real share of the
  // content, the same "generous but real bar" dotenv-exposure-check applies
  // to its own KEY=VALUE ratio -- guards against a prose page that happens
  // to mention "CREATE TABLE" once in passing.
  if (signalLines >= 2 && signalLines / totalContentLines >= 0.2) {
    return { severity: 'danger', headerLine: null, schemaSamples, schemaCount, dataCount, totalContentLines };
  }
  return null;
}

function classifyOne(result) {
  const { path } = result;
  if (!result.ok) {
    if (result.status === 401 || result.status === 403 || result.status === 404 || result.status === 410) {
      return { path, category: 'blocked', status: result.status, url: result.url, evidence: null, error: null };
    }
    return { path, category: 'error', status: result.status ?? null, url: result.url, evidence: null, error: result.error ?? 'request failed' };
  }

  const bytes = toUint8Array(result.bytes);
  const archive = matchArchiveSignature(bytes);
  if (archive) {
    return {
      path,
      category: 'exposed',
      status: result.status,
      url: result.url,
      kind: 'archive',
      severity: 'critical',
      evidence: { signature: archive.name, sampleHex: archive.sampleHex },
      error: null,
    };
  }

  const text = new TextDecoder('utf-8', { fatal: false }).decode(bytes);
  const sql = detectSqlDump(text);
  if (sql) {
    return {
      path,
      category: 'exposed',
      status: result.status,
      url: result.url,
      kind: 'sql-dump',
      severity: sql.severity,
      evidence: {
        headerLine: sql.headerLine,
        schemaSamples: sql.schemaSamples,
        schemaCount: sql.schemaCount,
        dataCount: sql.dataCount,
      },
      error: null,
    };
  }

  return { path, category: 'not-backup', status: result.status, url: result.url, evidence: null, error: null };
}

/**
 * @param {string} baseUrl - the site checked, for display only
 * @param {object[]} results - probe.mjs's per-path raw results
 */
export function buildReport(baseUrl, results) {
  const list = Array.isArray(results) ? results : [];
  const classified = list.map(classifyOne);

  const exposed = classified.filter((c) => c.category === 'exposed');
  const blocked = classified.filter((c) => c.category === 'blocked');
  const notBackup = classified.filter((c) => c.category === 'not-backup');
  const errors = classified.filter((c) => c.category === 'error');

  const findings = exposed.map((c) => {
    const critical = c.severity === 'critical';
    const title = critical
      ? `"${c.path}" is publicly readable and confirmed as a real ${c.kind === 'archive' ? 'archive' : 'SQL dump'}`
      : `"${c.path}" is publicly readable and looks like a SQL dump`;
    const detail =
      c.kind === 'archive'
        ? `The response matched the real ${c.evidence.signature} file-format header (${c.evidence.sampleHex}). ` +
          `This tool never lists, extracts, or reads a file from inside the archive -- confirming the header is ` +
          `already enough to know a backup is exposed.`
        : c.evidence.headerLine
          ? `The response opens with a real dump-tool header comment ("${c.evidence.headerLine}"). ` +
            `${c.evidence.dataCount} row-data statement(s) were seen but never read into this report -- ` +
            `only schema statements (table/column structure) are ever quoted.`
          : `The response has the structural shape of a SQL dump (${c.evidence.schemaCount} schema statement(s), ` +
            `${c.evidence.dataCount} row-data statement(s)) without an explicit dump-tool header. ` +
            `Row-data statement text is never quoted in this report -- only schema statements are.`;
    return {
      id: `backup-exposed-${c.path.replace(/[^a-z0-9]+/gi, '-')}`,
      severity: c.severity,
      kind: c.kind,
      path: c.path,
      url: c.url,
      evidence: c.evidence,
      title,
      detail,
    };
  });

  const criticalCount = findings.filter((f) => f.severity === 'critical').length;
  const dangerCount = findings.filter((f) => f.severity === 'danger').length;
  const exposedCount = findings.length;

  return {
    baseUrl,
    pathsChecked: classified.length,
    classified,
    findings,
    blocked,
    notBackup,
    errors,
    criticalCount,
    dangerCount,
    exposedCount,
    incomplete: errors.length > 0,
    ok: exposedCount === 0,
  };
}

check.mjs.text:
#!/usr/bin/env node
// CLI: sends one GET request per well-known backup-file path (backup.zip,
// backup.tar.gz, backup.sql, backup.sql.gz, db.sql, database.sql, dump.sql,
// site.zip) at a site's root and reports which ones are publicly readable --
// verified against a real archive's magic bytes or a real SQL dump's shape,
// not just an HTTP status. Your machine, real requests -- no request goes
// through this portfolio.
//
//   node check.mjs <site-url> [--json] [--timeout <ms>]
//
// Only run this against a site you own or are authorised to test -- treat it
// the same as you would `curl` aimed at someone else's server. This never
// sends anything but GET requests, reads at most 8KB per path, and never
// writes/modifies anything on the target or extracts anything from a
// matched archive.
//
// Exit code 0 when none of the checked paths is exposed; 1 when at least one
// is, or a request could not be completed at all.

import { checkSite } from './probe.mjs';
import { buildReport } from './analyze.mjs';

function formatText(report) {
  const lines = [];
  lines.push(`Site: ${report.baseUrl}`);
  lines.push(`Paths checked: ${report.pathsChecked}`);
  lines.push('');

  if (report.findings.length === 0) {
    lines.push('No exposed backup file found among the ones this tool checks.');
  } else {
    for (const f of report.findings) {
      lines.push(`!! [${f.severity.toUpperCase()}] ${f.title}`);
      lines.push(`     ${f.detail}`);
      lines.push(`     url: ${f.url}`);
      lines.push('');
    }
  }

  if (report.blocked.length > 0) {
    lines.push(`${report.blocked.length} path(s) cleanly blocked (401/403/404) -- a healthy outcome: ${report.blocked.map((c) => c.path).join(', ')}`);
  }
  if (report.notBackup.length > 0) {
    lines.push(`${report.notBackup.length} path(s) returned 200 but did not match a known archive or SQL dump shape (likely a soft-404 page): ${report.notBackup.map((c) => c.path).join(', ')}`);
  }
  if (report.errors.length > 0) {
    lines.push(`${report.errors.length} path(s) could not be checked: ${report.errors.map((c) => `${c.path} (${c.error})`).join('; ')}`);
  }

  lines.push('');
  lines.push(
    'This is evidence from the requests above, not a full security audit -- see README.md for ' +
      'what this tool does and does not check.',
  );
  return lines.join('\n');
}

function parseArgs(argv) {
  let siteUrl = null;
  let json = false;
  let timeoutMs;
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === '--json') json = true;
    else if (argv[i] === '--timeout') timeoutMs = Number(argv[++i]);
    else if (!argv[i].startsWith('--') && siteUrl === null) siteUrl = argv[i];
  }
  return { siteUrl, json, timeoutMs };
}

/** Pure orchestration: given a checkSite function (real network, or a stub in
 * tests), fetch and classify. Kept separate from main() so tests can inject
 * a fake `checkSiteFn` instead of hitting the network. */
export async function runCheck(siteUrl, { checkSiteFn = checkSite, timeoutMs } = {}) {
  const { results } = await checkSiteFn(siteUrl, timeoutMs ? { timeoutMs } : undefined);
  return buildReport(siteUrl, results);
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  if (!args.siteUrl) {
    console.error('Usage: node check.mjs <site-url> [--json] [--timeout <ms>]');
    console.error('Only run this against a site you own or are authorised to test.');
    process.exit(2);
  }
  try {
    // eslint-disable-next-line no-new
    new URL(args.siteUrl);
  } catch {
    console.error(`Not a valid URL: ${args.siteUrl}`);
    process.exit(2);
  }

  const report = await runCheck(args.siteUrl, { timeoutMs: args.timeoutMs });

  if (args.json) {
    console.log(JSON.stringify(report, null, 2));
  } else {
    console.log(formatText(report));
  }
  process.exit(report.ok ? 0 : 1);
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main();
}

probe.mjs.text:
// Real-network layer: sends one plain GET request to each of a short list of
// well-known backup-file paths at a site's root and returns exactly what came
// back -- status and a byte-capped *raw* body, nothing else. Deliberately the
// same module shape imported unmodified by the CLI (Node 22's built-in
// `fetch`) and by the browser page (`index.html` imports it directly), the
// same split `ventures/dotenv-exposure-check/probe.mjs` documents: this file
// only fetches, classification happens in analyze.mjs.
//
// Unlike the dotenv/git checkers, a real backup file is commonly *binary*
// (a zip, a gzip-compressed archive) rather than always text, so this module
// reads the capped response as raw bytes (a Uint8Array) rather than decoding
// to a string -- decoding first would corrupt exactly the archive
// magic-byte header analyze.mjs needs to tell a real backup apart from an
// unrelated 200 response. analyze.mjs is responsible for any text decoding
// it needs (e.g. to look for a SQL dump's header comment).
//
// The read is capped at a few kilobytes -- enough to read an archive's
// magic-byte header or a SQL dump tool's own header comment lines, never
// enough to be "downloading the backup". This tool confirms a backup file is
// present and readable; it does not fetch, unzip, or extract its contents.
//
// Whether a browser run can complete depends on the target's own CORS policy
// for a plain cross-origin GET -- most servers do not send permissive CORS
// headers on arbitrary static paths, so a cross-origin browser fetch commonly
// fails with a generic, status-less network error. This module never guesses
// which cause that was; it reports it as an unclassified `error`. The CLI,
// run from a machine rather than a browser tab, is not subject to CORS at all
// and is the one path guaranteed to complete.
//
// This module only ever talks to the one base URL the caller names, at the
// fixed list of paths below. It sends nothing anywhere but GET requests to a
// host the caller already supplied.

const DEFAULT_TIMEOUT_MS = 10_000;
const USER_AGENT =
  'backup-file-exposure-check/1 (+https://duncan-haywood.github.io/monorepo-projects/backup-file-exposure-check/)';
// A real archive's magic bytes live in the first handful of bytes, and a
// mysqldump/pg_dump/phpMyAdmin header comment lives in the first few lines.
// This cap is generous enough to classify a real exposure while bounding
// what this tool ever holds in memory, downloads from the target, or could
// be made to fetch on repeat -- it is deliberately far short of "the whole
// backup", the same restraint `git-exposure-check` applies to never
// requesting a repository's packed objects once exposure is confirmed.
const MAX_BODY_BYTES = 8192;

// The specific backup filenames checked: a mix of common archive
// (zip/tar.gz) and database-dump (sql/sql.gz) names drawn from the same
// "well-known filename" wordlists security testing methodologies already
// use for this exact reconnaissance step (OWASP's Web Security Testing
// Guide names "Review Old Backup and Unreferenced Files" explicitly, and
// SecLists' own "Backup files" wordlists carry this same short set of
// names). Kept short and well-documented rather than exhaustive, the same
// trade-off `dotenv-exposure-check` makes with its five dotenv filenames.
export const BACKUP_PATHS = [
  'backup.zip',
  'backup.tar.gz',
  'backup.sql',
  'backup.sql.gz',
  'db.sql',
  'database.sql',
  'dump.sql',
  'site.zip',
];

async function timedFetch(url, init, timeoutMs, fetchImpl) {
  const doFetch = fetchImpl ?? globalThis.fetch;
  if (typeof doFetch !== 'function') {
    throw new Error('no fetch implementation available in this environment');
  }
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    return await doFetch(url, { ...init, signal: controller.signal });
  } finally {
    clearTimeout(timer);
  }
}

/** Reads at most `maxBytes` of a response body as raw bytes, cancelling the
 * rest of the stream once the cap is reached rather than buffering a large
 * real backup file end to end. */
async function readCappedBytes(res, maxBytes) {
  if (!res.body?.getReader) {
    const buf = new Uint8Array(await res.arrayBuffer());
    return buf.length > maxBytes ? buf.slice(0, maxBytes) : buf;
  }
  const reader = res.body.getReader();
  const chunks = [];
  let total = 0;
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    total += value.byteLength;
    chunks.push(value);
    if (total >= maxBytes) {
      try { await reader.cancel(); } catch { /* best effort */ }
      break;
    }
  }
  const combined = new Uint8Array(Math.min(total, maxBytes));
  let offset = 0;
  for (const chunk of chunks) {
    const room = combined.length - offset;
    if (room <= 0) break;
    combined.set(room < chunk.length ? chunk.subarray(0, room) : chunk, offset);
    offset += Math.min(chunk.length, room);
  }
  return combined;
}

/** One GET request to `${baseUrl}/${path}`, capped and never throwing on an
 * ordinary HTTP or network failure -- those come back as `ok: false` with
 * `error` set, so a caller can tell "confirmed absent/blocked" (a clean
 * status) apart from "could not confirm either way" (a network error). */
export async function fetchBackupPath(baseUrl, path, { timeoutMs = DEFAULT_TIMEOUT_MS, fetchImpl } = {}) {
  const url = new URL(path, baseUrl.endsWith('/') ? baseUrl : `${baseUrl}/`).toString();
  let res;
  try {
    res = await timedFetch(
      url,
      { method: 'GET', headers: { 'user-agent': USER_AGENT, accept: '*/*' } },
      timeoutMs,
      fetchImpl,
    );
  } catch (err) {
    return { path, url, ok: false, status: null, bytes: null, error: err.message ?? String(err) };
  }
  if (!res.ok) {
    return { path, url, ok: false, status: res.status, bytes: null, error: `HTTP ${res.status}` };
  }
  let bytes;
  try {
    bytes = await readCappedBytes(res, MAX_BODY_BYTES);
  } catch (err) {
    return { path, url, ok: false, status: res.status, bytes: null, error: err.message ?? String(err) };
  }
  return { path, url, ok: true, status: res.status, bytes, error: null };
}

/** Full run: fetch every path in `BACKUP_PATHS` (or an explicit subset)
 * against `baseUrl`, in parallel. Never throws on a per-path failure --
 * every path gets a result, `ok: false` and all. */
export async function checkSite(baseUrl, { paths = BACKUP_PATHS, timeoutMs, fetchImpl } = {}) {
  if (!baseUrl) throw new Error('a base URL is required');
  const results = await Promise.all(
    paths.map((path) => fetchBackupPath(baseUrl, path, { timeoutMs, fetchImpl })),
  );
  return { baseUrl, results };
}

usage.mjs.text:
// Records an anonymous, aggregate-only local usage count: the event name and
// the current day, kept in the visitor's own browser. It never stores the
// target URL or anything about what was checked -- that is exactly the kind
// of thing that must not be transmitted anywhere, and this tool never reads
// it off the visitor's machine either. Same shape as every other venture's
// usage.mjs in this portfolio (see dotenv-exposure-check/usage.mjs).

const STORAGE_KEY = 'backup-file-exposure-check-usage';

function honorsBrowserSignal() {
  try {
    return globalThis.navigator?.doNotTrack === '1' || globalThis.navigator?.globalPrivacyControl === true;
  } catch {
    return false;
  }
}

export function recordUsage(storage = globalThis.localStorage, optedOut = false, event = 'check_run') {
  if (optedOut || !storage || readOptOut(storage) || honorsBrowserSignal()) return;
  try {
    const today = new Date().toISOString().slice(0, 10);
    const current = JSON.parse(storage.getItem(STORAGE_KEY) || '{}');
    current[event] = (current[event] || 0) + 1;
    current.last_day = today;
    storage.setItem(STORAGE_KEY, JSON.stringify(current));
  } catch {
    // A browser refusing site data must not stop the page computing a result.
  }
}

// The opt-out choice is kept in its own key, not in the counters:
// opting out *removes* the counters, so a flag stored inside them would
// be deleted by the very act it records. `recordUsage` above consults it
// directly as well as taking the caller's argument -- a stored preference
// that only one line of page wiring reads is one line away from being
// forgotten.
export function readOptOut(storage = globalThis.localStorage) {
  try {
    return storage?.getItem(`${STORAGE_KEY}-opt-out`) === '1';
  } catch {
    // A blocked or full store must never be read as consent.
    return false;
  }
}

export function writeOptOut(storage = globalThis.localStorage, optedOut = false) {
  if (!storage) return;
  // Independent writes, counters first: sharing one try means a setItem
  // that throws on a full quota skips the delete entirely, and the
  // visitor gets neither half of what the control promised.
  if (optedOut) {
    try { storage.removeItem(STORAGE_KEY); } catch { /* storage is optional */ }
    try { storage.setItem(`${STORAGE_KEY}-opt-out`, '1'); } catch { /* storage is optional */ }
  } else {
    try { storage.removeItem(`${STORAGE_KEY}-opt-out`); } catch { /* storage is optional */ }
  }
}
